add(2024,54,'lipid','Nişastada amilopektin genellikle çoğunluğu, amiloz daha küçük kısmı oluşturur. Seçenek E tipik oranları ters vermektedir.','Sükroz iki anomerik karbonun glikozidik bağla birleşmesidir. | Glikojen amilopektine göre daha sık dallanır. | Laktoz galaktoz ve glukozu β(1→4) bağlar. | Maltoz iki glukozu α(1→4) bağlar. | Klasik nişastada çoğunluk amilopektindir; yaklaşık oranlar ters yazılmıştır ve bitkiye göre değişebilir.')
add(2024,55,'spectro','Kuvars UV yanında görünür ışığı da geçirebilir. Bu nedenle kuvarsla yalnız UV ölçülebileceği ifadesi yanlıştır.','Kör arka plan absorbansını düzeltir. | Derişim artınca doğrusal aralıkta absorbans artar ve transmittans azalır. | Yol uzunluğu artınca absorbans artar. | Uygun cihazla hem UV hem görünür bölgede ölçüm yapılabilir. | Kuvars yalnız UV’ye özgü değildir; görünür bölgede de kullanılabilir.')
clone(2024,56,2023,62,'BA CDE'.replace(' ',''))
add(2024,57,'energy','Basit Michaelis–Menten modelinde Km, Vmax/2 hızındaki substrat derişimidir. Düşük Km aynı oransal hız için daha az substrat gerektirdiğini gösterir.','Düşük Km’yi düşük afiniteyle eşleştirmek bu basit modelde terstir. | Km belirli enzim-substrat çifti ve deney koşullarına bağlıdır. | Bir enzimin farklı substratlarla Km değerleri farklı olabilir. | Basit modelde düşük Km daha yüksek görünür substrat ilgisiyle ilişkilidir. | Basit doygunluk modelinde yarı hız/yarı doluluk koşulunu tanımlar; teknik tanım substrat derişimidir.')
add(2024,58,'psych','Bipolar bozukluk, mani/hipomani ve depresif dönemlerle ilişkili duygudurum bozukluğu olarak sınıflandırılır. Güncel sınıflamada bipolar ve ilişkili bozukluklar ayrı başlıktır.','Kaygı bozukluklarının temel özelliği korku/kaygıdır; bipoların temel sınıfı değildir. | Kişilik bozuklukları kalıcı örüntülerdir; bipolar duygudurum dönemleriyle ayrılır. | Verilen geleneksel seçeneklerde duygudurum bozuklukları doğru üst gruptur. | Psikotik belirtiler eşlik edebilir; bu temel sınıflamayı psikotik bozukluk yapmaz. | Yeme bozuklukları beslenme ve beden algısıyla ilişkili ayrı gruptur.')
add(2024,59,'psych','Önce koşulsuz uyaran doğal tepkiyi doğurur; sonra nötr uyaran bununla eşleştirilir. Öğrenme sonrası eski nötr uyaran koşullu uyaran olarak koşullu tepki oluşturur: III→II→I.','Koşullu tepki eşleşmeden önce yerleştirilmiştir; sıra yanlıştır. | Öğrenilmiş tepki doğal ilişkiden ve eşleşmeden önce yazılmıştır. | Nötr eşleşme temel koşulsuz ilişki gösterilmeden öne alınmıştır. | Koşullu ilişkinin ilk sırada olması öğrenme sürecini ters çevirir. | Doğal ilişki, eşleşme ve öğrenilmiş ilişki sırası III–II–I’dir.')
add(2024,60,'psych','Edim, organizmanın yaptığı davranış/eylemdir. Edimsel koşullanmada davranışın sonucu, o davranışın yeniden ortaya çıkma olasılığını etkiler.','Duygu davranışın sonucu veya eşlikçisi olabilir; edimin tanımı değildir. | Düşünce bu sorudaki gözlenen edim/eylem karşılığını vermez. | Edim organizmanın yaptığı eylemdir. | Ceza edimin kendisi değil davranışı azaltan sonuç ilişkisidir. | Ödül sonuç olabilir; yapılan davranışın adı değildir.')
add(2024,62,'psych','Piaget evreleri duyu-motor, işlem öncesi, somut işlemler ve soyut/formel işlemler sırasındadır. Yaklaşık yaşlar 0–2, 2–7, 7–11 ve 11+ şeklindedir.','Somut ve soyut işlemler başlangıca alınmış; sıra yanlıştır. | III–IV–II–I, duyu-motordan soyut işlemlere doğru sıradır. | İşlem öncesi, duyu-motordan sonra gelmelidir. | Somut işlemler işlem öncesinden sonra gelir; II ve IV ters yerleştirilmiştir. | Somut işlemler duyu-motordan önce gelmez.')
